check_code:
faces=set("PQRSTU")
adj={"P","T","Q","U"}
opp=faces-adj-{"R"}
assert len(opp)==1
ans=opp.pop()
opts={"A":"U","B":"Q","C":"S","D":"T"}
assert ans==opts["C"]
for k in "ABD": assert ans!=opts[k]

groups={"small top triangle":3,"triangle below it":1,"lower right triangle split by vertical":3,"triangle under rectangle corner":1}
n=sum(groups.values())
opts={"A":6,"B":8,"C":4,"D":5}
assert n==opts["B"]
for k in "ACD": assert n!=opts[k]

regions={"T":35,"E":42,"A":56,"TE":4,"TA":6,"EA":8,"TEA":3}
n=sum(v for k,v in regions.items() if len(k)>1)
opts={"A":21,"B":15,"C":113,"D":18}
assert n==opts["A"]
for k in "BCD": assert n!=opts[k]

regions={"M":78,"D":75,"C":76,"MD":23,"MC":45,"DC":34,"MDC":24}
n=sum(v for k,v in regions.items() if "M" in k and "D" in k)
opts={"A":47,"B":34,"C":23,"D":24}
assert n==opts["A"]
for k in "BCD": assert n!=opts[k]
